WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pb_cd_case'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '分情况条件概率', 'kp-pb-cd-case', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "条件概率直观判定"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知发生某事，等于强行把“世界（样本空间）”缩小了！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“有两个孩子，已知其中一个是女孩，问另一个也是女孩的概率？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、致命陷阱（男女概率1/2）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无数人会秒答 1/2。大错特错！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "生两个孩子，本来有 4 种平等的世界：(男男), (男女), (女男), (女女)。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“已知其中一个是女孩”，说明 (男男) 这个世界崩塌了，不复存在！现在总样本空间只剩下 3 种：(男女), (女男), (女女)。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "其中另一个也是女孩的，只有 (女女) 这一种。所以概率是 1/3！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略排列顺序：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "(男女) 和 (女男) 在概率学里是两个完全不同的世界（大的是男的和小的是男的）。在数总情况时绝对不能把它们当成一个！"}]}]}]}$$ AS jsonb), NULL, '分情况条件概率的核心考点与实战推导。', category_node.id, CAST('["数量关系", "概率问题", "分情况条件概率"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pb_cd_case", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
